	/** Every accepted combination is checked together, including after any individually unsafe names are removed. */
	private static Set<String> retainableNames(Set<String> names, Predicate<Set<String>> proof) {
		if (proof.test(names)) {
			return names;
		}
		Set<String> candidates = new HashSet<>();
		for (String name : names) {
			if (proof.test(Set.of(name))) {
				candidates.add(name);
			}
		}
		if (proof.test(candidates)) {
			return candidates;
		}
		Set<String> retained = new HashSet<>();
		for (String name : candidates) {
			retained.add(name);
			if (!proof.test(retained)) {
				retained.remove(name);
			}
		}
		return retained;
	}

	/** Compatible left/current values win only for names the complete retained set is proven to preserve. */
	private static boolean mergeInput(BindingSet logical, Set<String> retainable, QueryBindingSet result) {
		for (Binding binding : logical) {
			String name = binding.getName();
			Value value = binding.getValue();
			if (value == null || !retainable.contains(name)) {
				continue;
			}
			Value produced = result.getValue(name);
			if (produced != null && !produced.equals(value)) {
				return false;
			}
			boolean supplied = GraphFrameBindings.isSupplied(logical, name);
			if (supplied) {
				if (produced != value || !GraphFrameBindings.isSupplied(result, name)) {
					GraphFrameBindings.supply(result, name, value);
				}
			} else if (produced != value || GraphFrameBindings.isSupplied(result, name)) {
				result.setBinding(name, value);
			}
		}
		return true;
	}

	private record GraphInputs(GraphIdentity active, Map<String, GraphValueIdentity> parameters) {
		private static GraphInputs of(ActiveGraph active, Map<String, Value> parameters) {
			Map<String, GraphValueIdentity> identities = new HashMap<>(parameters.size() * 2);
			parameters.forEach((name, value) -> identities.put(name, new GraphValueIdentity(value)));
			return new GraphInputs(GraphIdentity.of(active), identities);
		}
	}

	private record GraphIdentity(GraphValueIdentity logical, GraphValueIdentity physical) {
		private static GraphIdentity of(ActiveGraph active) {
			return active == null ? null
					: new GraphIdentity(new GraphValueIdentity(active.logicalGraph()),
							new GraphValueIdentity(active.physicalGraph()));
		}
	}

	/** GRAPH replay keys preserve the same private identity that graph selection uses, not just an RDF label. */
	private record GraphValueIdentity(Value value) {
		@Override
		public boolean equals(Object other) {
			if (!(other instanceof GraphValueIdentity that)) {
				return false;
			}
			if (value == that.value) {
				return true;
			}
			if (value instanceof RemoteBNode || that.value instanceof RemoteBNode) {
				return value instanceof RemoteBNode first && that.value instanceof RemoteBNode second
						&& RemoteBNode.sameTrustedIdentity(first, second);
			}
			if (value instanceof RepositoryBNode || that.value instanceof RepositoryBNode) {
				return value instanceof RepositoryBNode first && that.value instanceof RepositoryBNode second
						&& first.getID().equals(second.getID()) && first.getRawID().equals(second.getRawID())
						&& first.isReference() == second.isReference();
			}
			if (value instanceof GeneratedBNode || that.value instanceof GeneratedBNode) {
				return value instanceof GeneratedBNode first && that.value instanceof GeneratedBNode second
						&& first.getID().equals(second.getID());
			}
			return Objects.equals(value, that.value);
		}

		@Override
		public int hashCode() {
			if (value instanceof RemoteBNode remote) {
				RemoteBNode.Provenance provenance = remote.getProvenance();
				if (provenance == null) {
					return System.identityHashCode(remote);
				}
				if (provenance.canonicalResultID() && provenance.identityScope() != null) {
					return 31 * System.identityHashCode(provenance.identityScope())
							+ provenance.remoteID().hashCode();
				}
				return remote.getID().hashCode();
			}
			if (value instanceof RepositoryBNode repository) {
				return Objects.hash(repository.getID(), repository.getRawID(), repository.isReference());
			}
			if (value instanceof GeneratedBNode generated) {
				return Objects.hash(GeneratedBNode.class, generated.getID());
			}
			return Objects.hashCode(value);
		}
	}

	private static final class Rows implements AutoCloseable {
		private final Invocation invocation;
		private final Map<Long, ReplayRow> values;
		private final AtomicReference<CloseableIteration<BindingSet>> source;
		private final Object provenanceLock = new Object();
		private RemoteBNode.SpillScope provenance;
		private long size;
		private boolean exhausted;

		private Rows(Invocation invocation, Map<Long, ReplayRow> values, CloseableIteration<BindingSet> source) {
			this.invocation = invocation;
			this.values = values;
			this.source = new AtomicReference<>(source);
		}

		private synchronized boolean read() {
			CloseableIteration<BindingSet> producer = source.get();
			if (exhausted || producer == null || invocation.closed.get() || invocation.cancelled) {
				return false;
			}
			try {
				if (!producer.hasNext()) {
					exhausted = true;
					closeSource();
					return false;
				}
				if (invocation.closed.get() || invocation.cancelled) {
					return false;
				}
				QueryBindingSet row = new QueryBindingSet(producer.next());
				row.setBindingFrame(null);
				values.put(size++, new ReplayRow(row, this));
				return true;
			} catch (RuntimeException | Error failure) {
				closeSuppressed(this, failure);
				throw failure;
			}
		}

		private void closeSource() {
			CloseableIteration<BindingSet> closing = source.getAndSet(null);
			if (closing != null) {
				closing.close();
			}
		}

		@Override
		public void close() {
			try {
				closeSource();
			} finally {
				synchronized (provenanceLock) {
					if (provenance != null) {
						provenance.close();
					}
				}
			}
		}

		private RemoteBNode.SpillScope provenance() {
			if (provenance == null) {
				provenance = new RemoteBNode.SpillScope();
			}
			return provenance;
		}
	}

	/** Keeps normal in-memory rows direct; private spill streams retain trusted identities at every nesting depth. */
	private static final class ReplayRow implements Serializable {
		private static final long serialVersionUID = 1L;
		private transient BindingSet direct;
		private transient Rows owner;
		private byte[] serialized;

		private ReplayRow(BindingSet direct, Rows owner) {
			this.direct = direct;
			this.owner = owner;
		}

		private BindingSet bindings(Rows rows) {
			if (direct != null) {
				return direct;
			}
			synchronized (rows.provenanceLock) {
				RemoteBNode.SpillScope scope = rows.provenance();
				try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(serialized)) {
					{
						enableResolveObject(true);
					}

					@Override
					protected Object resolveObject(Object value) {
						return scope.resolve(value);
					}
				}) {
					return (BindingSet) input.readObject();
				} catch (IOException | ClassNotFoundException failure) {
					throw new QueryEvaluationException("Unable to read a binding-frame replay row", failure);
				}
			}
		}

		private void writeObject(ObjectOutputStream output) throws IOException {
			byte[] bytes = serialized;
			if (bytes == null) {
				synchronized (owner.provenanceLock) {
					RemoteBNode.SpillScope scope = owner.provenance();
					ByteArrayOutputStream buffer = new ByteArrayOutputStream();
					try (ObjectOutputStream stream = new ObjectOutputStream(buffer) {
						{
							enableReplaceObject(true);
						}

						@Override
						protected Object replaceObject(Object value) {
							return scope.replace(value);
						}
					}) {
						stream.writeObject(direct);
					}
					bytes = buffer.toByteArray();
				}
			}
			output.writeInt(bytes.length);
			output.write(bytes);
		}

		private void readObject(ObjectInputStream input) throws IOException {
			int length = input.readInt();
			if (length < 0) {
				throw new InvalidObjectException("Invalid binding-frame replay row length");
			}
			serialized = input.readNBytes(length);
			if (serialized.length != length) {
				throw new EOFException("Incomplete binding-frame replay row");
			}
		}
	}

	private static Throwable combine(Throwable first, Throwable next) {
		if (first == null) {
			return next;
		}
		if (first != next) {
			first.addSuppressed(next);
		}
		return first;
	}

	private static void rethrow(Throwable failure) {
		if (failure instanceof Error error) {
			throw error;
		}
		if (failure instanceof RuntimeException exception) {
			throw exception;
		}
	}

	private static void closeSuppressed(AutoCloseable resource, Throwable failure) {
		try {
			resource.close();
		} catch (Throwable closing) {
			combine(failure, closing);
		}
	}
